from .server_api import ServerApi


class OpticalAttenuatorClient(object):
    def __init__(self):
        self.server_api = None

    def setup_attenuator(self,
                         server_ip,
                         vendor,
                         location,
                         server_port=8080,
                         model=None):
        self.server_api = ServerApi(server_ip, server_port)
        self.server_api.setup_attenuator(vendor, location, model)

    def get_current_attenuation(self, attenuator_port):
        return self.server_api.get_current_attenuation(attenuator_port)

    def set_attenuation(self, attenuator_port, attenuation_value):
        self.server_api.set_attenuation(attenuator_port, attenuation_value)
